GRANT UPDATE (note, mentions, edited_at, deleted_at) ON public.task_events TO authenticated;
CREATE POLICY "Authors edit own local comments" ON public.task_events FOR UPDATE TO authenticated USING (kind = 'comment' AND source = 'virtual_space' AND actor_id = auth.uid() AND deleted_at IS NULL AND EXISTS (SELECT 1 FROM public.teamspace_members m WHERE m.teamspace_id = task_events.teamspace_id AND m.user_id = auth.uid())) WITH CHECK (kind = 'comment' AND source = 'virtual_space' AND actor_id = auth.uid() AND EXISTS (SELECT 1 FROM public.teamspace_members m WHERE m.teamspace_id = task_events.teamspace_id AND m.user_id = auth.uid()));